-- ============================================
-- LUMA — Thème 8 : 3e scénario COURT x4 — Un premier indice mystérieux
-- ============================================


update scenarios set content = '{"characters": {"old_woman": "la vieille femme"}, "start_node": "n1", "nodes": {"n1": {"speaker": "old_woman", "text": "(An old woman approaches, eyes glinting with secrets.) You seek the artifact, don''t you?", "text_fr": "(Une vieille femme s''approche, les yeux brillants de secrets.) Vous cherchez l''artefact, n''est-ce pas ?", "choices": [{"text": "Yes, how did you know? Do you have information?", "text_fr": "Oui, comment le saviez-vous ? Vous avez des informations ?", "next": "n2"}, {"text": "Who are you, and what do you know of my quest?", "text_fr": "Qui êtes-vous, et que savez-vous de ma quête ?", "next": "n2b"}]}, "n2": {"speaker": "old_woman", "text": "I see many things, traveler. The artifact rests where shadows meet moonlight.", "text_fr": "Je vois beaucoup de choses, voyageur. L''artefact repose là où les ombres rencontrent le clair de lune.", "choices": [{"text": "That''s quite cryptic — could you explain more clearly?", "text_fr": "C''est assez énigmatique — vous pourriez expliquer plus clairement ?", "next": "n3"}, {"text": "Shadows meet moonlight... a cave, perhaps?", "text_fr": "Les ombres rencontrent le clair de lune... une grotte, peut-être ?", "next": "n3b"}]}, "n2b": {"speaker": "old_woman", "text": "I am but a keeper of old secrets. Your quest is written in the stars, child.", "text_fr": "Je ne suis qu''une gardienne de vieux secrets. Votre quête est écrite dans les étoiles, enfant.", "choices": [{"text": "Please, any guidance would help me greatly.", "text_fr": "S''il vous plaît, tout conseil m''aiderait grandement.", "next": "n3"}]}, "n3": {"speaker": "old_woman", "text": "Seek the place where shadows meet moonlight — a clearing deep in the forest, at night.", "text_fr": "Cherchez l''endroit où les ombres rencontrent le clair de lune — une clairière au cœur de la forêt, la nuit.", "choices": [{"text": "Thank you, wise one. I''ll seek this clearing.", "text_fr": "Merci, sage. Je vais chercher cette clairière.", "next": "n4"}]}, "n3b": {"speaker": "old_woman", "text": "Clever guess, but no — a clearing, where the ancient trees part just enough for moonlight to fall.", "text_fr": "Devinette intelligente, mais non — une clairière, où les arbres anciens s''écartent juste assez pour que le clair de lune tombe.", "choices": [{"text": "A clearing at night, then. I understand now.", "text_fr": "Une clairière la nuit, alors. Je comprends maintenant.", "next": "n4"}]}, "n4": {"speaker": "old_woman", "text": "But beware — the artifact is guarded, and not all who seek it return.", "text_fr": "Mais attention — l''artefact est gardé, et tous ceux qui le cherchent ne reviennent pas.", "choices": [{"text": "I accept the risk. My quest demands nothing less.", "text_fr": "J''accepte le risque. Ma quête n''exige rien de moins.", "next": "n5"}, {"text": "What kind of guardian protects it?", "text_fr": "Quel genre de gardien le protège ?", "next": "n5b"}]}, "n5": {"speaker": "old_woman", "text": "Brave words. May your courage match your determination, traveler.", "text_fr": "Paroles courageuses. Que votre courage égale votre détermination, voyageur.", "choices": [{"text": "Thank you for this vital clue. I must be going.", "text_fr": "Merci pour cet indice vital. Je dois y aller.", "next": "end_clue"}]}, "n5b": {"speaker": "old_woman", "text": "Ancient magic, older than the forest itself. Tread carefully, child.", "text_fr": "Une magie ancienne, plus vieille que la forêt elle-même. Marchez prudemment, enfant.", "choices": [{"text": "I will heed your warning. Thank you for this knowledge.", "text_fr": "Je vais tenir compte de votre avertissement. Merci pour ce savoir.", "next": "end_clue"}]}, "end_clue": {"speaker": "old_woman", "text": "Go now, and may the moon light your path truly.", "text_fr": "Allez maintenant, et que la lune éclaire vraiment votre chemin.", "end": true, "ending_label": "Premier indice mystérieux obtenu 🔮🌙"}}}'::jsonb, is_playable = true
where title = 'Un premier indice mystérieux'
  and theme_id = (select id from scenario_themes where position = 8 and language_id = (select id from languages where code = 'en'));
